//! Proof/test lane definitions and command generation.
//!
//! Each lane maps to a shell command with crate-specific arguments.

use std::path::Path;

#[derive(Debug, Clone)]
pub struct Lane {
    pub name: String,
    pub required: bool,
}

pub fn lane_command(lane: &Lane, crate_name: &str, workspace_root: &Path) -> Vec<String> {
    match lane.name.as_str() {
        "test" => vec![
            "cargo".into(),
            "test".into(),
            "-p".into(),
            crate_name.into(),
        ],
        "clippy" => vec![
            "cargo".into(),
            "clippy".into(),
            "-p".into(),
            crate_name.into(),
            "--".into(),
            "-D".into(),
            "warnings".into(),
        ],
        "nextest" => vec![
            "cargo".into(),
            "nextest".into(),
            "run".into(),
            "-p".into(),
            crate_name.into(),
        ],
        "kani" => vec![
            "cargo".into(),
            "kani".into(),
            "-p".into(),
            crate_name.into(),
        ],
        "miri" => vec![
            "cargo".into(),
            "+nightly".into(),
            "miri".into(),
            "test".into(),
            "-p".into(),
            crate_name.into(),
        ],
        "loom" => vec![
            "cargo".into(),
            "test".into(),
            "-p".into(),
            crate_name.into(),
            "--features".into(),
            "loom".into(),
        ],
        "fuzz" => vec![
            "cargo".into(),
            "fuzz".into(),
            "run".into(),
            format!("{crate_name}_fuzz"),
        ],
        "mutants" => vec![
            "cargo".into(),
            "mutants".into(),
            "-p".into(),
            crate_name.into(),
            "--no-times".into(),
        ],
        "coverage" => vec![
            "cargo".into(),
            "llvm-cov".into(),
            "--no-report".into(),
            "-p".into(),
